const todosChamados = $input.all().map(item => item.json);

// 1. Criar a lista de chamados ABERTOS (ignorando os Fechados=5 e Resolvidos=6)
const chamadosAbertos = todosChamados
  .filter(c => c.status !== 5 && c.status !== 6)
  .map(c => ({
    id: c.id,
    titulo: c.name,
    descricao: c.content,
    local_id: c.locations_id
  }));

// 2. Filtrar apenas os chamados NOVOS (Status = 1) que precisam de triagem agora
const chamadosNovos = todosChamados.filter(c => c.status === 1);

const saida = [];

// 3. Montar o pacote perfeito para a IA (O Novo + O Histórico)
for (const novo of chamadosNovos) {
  // Removemos o próprio chamado novo da lista de histórico para a IA não achar que ele é cópia de si mesmo!
  const historicoParaComparar = chamadosAbertos.filter(aberto => aberto.id !== novo.id);

  saida.push({
    json: {
      chamado_atual: {
        id: novo.id,
        titulo: novo.name,
        descricao: novo.content,
        local_id: novo.locations_id
      },
      historico_abertos: historicoParaComparar
    }
  });
}

return saida;

