return $input.all().map(item => {
  try {
    const parts = item.json?.content?.parts;
    if (parts && parts.length > 0) {
      const jsonLimpo = JSON.parse(parts[0].text);
      return { json: jsonLimpo };
    }
  } catch (error) {
    return { json: { classificacao: "ERRO", erro: "Falha no parse" } };
  }
  return { json: { classificacao: "ERRO", erro: "Sem conteúdo" } };
});

// Mapeia todos os itens que chegam (seja 1 ou 5 de cada vez)
return $input.all().map(item => {
  try {
    // Verifica se a estrutura básica da IA existe
    const parts = item.json?.content?.parts;

    if (parts && parts.length > 0) {
      // Transforma a string de texto em um objeto JSON real
      const jsonLimpo = JSON.parse(parts[0].text);

      // Retorna o objeto processado para o Switch
      return { json: jsonLimpo };
    }
  } catch (error) {
    // Se a IA alucinar ou o JSON vier quebrado, define como 'false' para não travar o fluxo
    return { 
      json: { 
        potencial_duplicata: false, 
        erro: "Falha no parse",
        original: item.json?.content?.parts[0]?.text 
      } 
    };
  }

  // Caso o item venha totalmente vazio
  return { json: { potencial_duplicata: false, erro: "Sem conteúdo da IA" } };
});
